WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT session_id, device_code, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, BIT_OR(status_bits) AS status_bits_bit_or, CORR(humidity, status_bits) AS corr_humidity_status_bits, RANK() OVER (PARTITION BY session_id ORDER BY CORR(humidity, status_bits) DESC) AS corr_humidity_status_bits_rank FROM sessions_device_readings GROUP BY session_id, device_code ORDER BY corr_humidity_status_bits ASC;
